import numpy as np
from collections import deque
sk=np.load('skel.npy').astype(bool)
H,W=sk.shape
def neigh(p):
    y,x=p
    out=[]
    for dy in (-1,0,1):
        for dx in (-1,0,1):
            if dy==0 and dx==0: continue
            yy,xx=y+dy,x+dx
            if 0<=yy<H and 0<=xx<W and sk[yy,xx]: out.append((yy,xx))
    return out
pts=[tuple(p) for p in np.argwhere(sk)]
deg={p:len(neigh(p)) for p in pts}
nodes=set(p for p in pts if deg[p]>=3)
clusters=[];seen=set()
for p in nodes:
    if p in seen: continue
    q=deque([p]);comp=[];seen.add(p)
    while q:
        c=q.popleft();comp.append(c)
        for n in neigh(c):
            if n in nodes and n not in seen:
                seen.add(n);q.append(n)
    clusters.append(comp)
for c in sorted(clusters,key=lambda c:-len(c)):
    ys=[p[0] for p in c];xs=[p[1] for p in c]
    print(len(c),'x',min(xs),max(xs),'y',min(ys),max(ys))
